import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load image texture
  const imageTexture = ctx.textureLoader.load(config.assetPaths.imageUrl);

  // Create plane geometry with aspect ratio 512:320 = 1.6:1
  const width = 1.6;
  const height = 1;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Create material with texture using TSL nodes
  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = texture(imageTexture);

  // Create mesh
  const imageMesh = new THREE.Mesh(geometry, material);
  group.add(imageMesh);

  // Render text content via fontAtlas
  if (config.textContent && config.textContent.length > 0) {
    const textContent = config.textContent[0];
    const textMesh = ctx.fontAtlas.render(textContent, {
      fontName: 'Lora',
      fontSize: 0.42,
      fontWeight: 400,
      color: config.colors.ink,
      align: 'center',
      anchorX: 0.5,
      anchorY: 0.5
    });

    // Position text in front of image
    textMesh.position.z = 0.05;
    group.add(textMesh);
  }

  // Apply scene placement
  if (config.scenePosition) {
    group.position.set(...config.scenePosition);
  }
  if (config.sceneRotation) {
    group.rotation.set(...config.sceneRotation);
  }
  if (config.sceneScale) {
    group.scale.set(...config.sceneScale);
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
    gsap.killTweensOf(group);
  };

  // No event handlers (static composition)
  group.userData.handlers = {};

  return group;
}
